{"description":"Source 2: GitHub Security Advisories collection - Tier 1 (last 2 years)","command":"# Source 2: GitHub Security Advisories
echo "---Source 2: GitHub Security Advisories for ecosystem: npm, package: Overmind---"

# Compute cutoff date: 2 years before today
CUTOFF=$(date -v-2y +%Y-%m-%dT00:00:00Z 2>/dev/null || date -d '2 years ago' +%Y-%m-%dT00:00:00Z)
echo "Cutoff date for Tier 1: $CUTOFF"

# Query GitHub GraphQL API for security advisories (last 2 years)
echo "Fetching advisories from last 2 years..."
ADVISORIES_2YR=$(gh api graphql --paginate -f query='
query($cursor: String) {
  securityAdvisories(first: 100, after: $cursor, orderBy: {field: PUBLISHED_AT, direction: DESC}) {
    pageInfo { hasNextPage endCursor }
    nodes {
      ghsaId
      publishedAt
      severity
      summary
      cvss { score vectorString }
      cwes(first: 5) { nodes { cweId name } }
      identifiers { type value }
      vulnerabilities(first: 20) {
        nodes {
          package { name ecosystem }
          vulnerableVersionRange
          firstPatchedVersion { identifier }
        }
      }
    }
  }
}' 2>/dev/null | jq --arg cutoff "$CUTOFF" '[.data.securityAdvisories.nodes[] | select(.publishedAt >= $cutoff)] | sort_by(.publishedAt) | reverse')

echo "Tier 1 (last 2yr) advisories count: $(echo "$ADVISORIES_2YR" | jq 'length')""}

